script:
(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const arm = () => {
        const root = document.documentElement;
        root.classList.add("gr-js");
        const io = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                entry.target.classList.add("gr-in");
                io.unobserve(entry.target);
            }
        }, { threshold: 0.12, rootMargin: "0px 0px -8% 0px" });
        document.querySelectorAll(".gr-rise").forEach((el) => io.observe(el));

        // the record spins with scroll; the tonearm angle is page progress
        let ticking = false;
        const update = () => {
            ticking = false;
            const doc = document.documentElement;
            const travel = Math.max(1, doc.scrollHeight - window.innerHeight);
            root.style.setProperty("--spin",
                ((window.scrollY * 0.4) % 360).toFixed(2) + "deg");
            root.style.setProperty("--armp",
                Math.min(1, window.scrollY / travel).toFixed(4));
        };
        const onScroll = () => {
            if (ticking) return;
            ticking = true;
            requestAnimationFrame(update);
        };
        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll, { passive: true });
        update();

        // the NOW PLAYING pill retunes as sections cross mid-viewport
        const pill = document.querySelector("[data-nowplaying]");
        if (pill) {
            const tracks = new IntersectionObserver((entries) => {
                for (const entry of entries) {
                    if (!entry.isIntersecting) continue;
                    pill.textContent =
                        entry.target.getAttribute("data-tune");
                }
            }, { rootMargin: "-42% 0px -52% 0px" });
            document.querySelectorAll("[data-tune]").forEach(
                (el) => tracks.observe(el));
        }
    };
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", arm);
    } else {
        arm();
    }
})();
